class Solution {
public:
    int numTilings(int n) {
        if (n <= 2) return n;
        if (n == 3) return 5;
        const int MOD = 1'000'000'007;
        long long a = 1, b = 2, c = 5;
        for (int i = 4; i <= n; ++i) {
            long long nxt = (2 * c + a) % MOD;
            a = b;
            b = c;
            c = nxt;
        }
        return c;
    }
};

class Solution {
    public int numTilings(int n) {
        if (n <= 2) return n;
        if (n == 3) return 5;
        final int MOD = 1_000_000_007;
        long a = 1, b = 2, c = 5;
        for (int i = 4; i <= n; i++) {
            long nxt = (2 * c + a) % MOD;
            a = b;
            b = c;
            c = nxt;
        }
        return (int)c;
    }
}

var numTilings = function(n) {
    if (n <= 2) return n;
    if (n === 3) return 5;
    const MOD = 1000000007;
    let a = 1n, b = 2n, c = 5n;
    for (let i = 4; i <= n; i++) {
        const nxt = (2n * c + a) % BigInt(MOD);
        a = b;
        b = c;
        c = nxt;
    }
    return Number(c);
};
